 r={'id':f'applesauce-control-{idx}','source_id':nap,'source_label':'Napier et al. 2024','primary_url':'https://www.cdc.gov/mmwr/volumes/73/wr/mm7328a2.htm','dataset_family':'cinnamon-applesauce-outbreak-2023','dependent_pages':['wiki/ingredients/applesauce.md'],'chain_order':idx,'control':control,'stage':stage,'material':'Implicated apple-cinnamon fruit puree; ingredient-control inference explicitly distinguished','material_filter':'Apple-cinnamon puree','audiences':aud,'tested_scale':'Public-health response' if idx==3 else 'Outbreak investigation; no control trial','evidence_kind':kind,'action_summary':action,'duration':'2023–2024 investigation and response','conditions_summary':'Known implicated products; not a blanket claim about all cinnamon or applesauce.','unit_summary':'No independently assigned intervention units or quantified food-effect estimate.','tradeoff_summary':'Nutrition, sensory quality, yield, waste and implementation costs not quantified.','verification_summary':'Trace product identity and investigate actual lots; this proposal has no experimentally measured treatment efficacy.','comparator':comp,'design':'Observational outbreak investigation and public-health response; linked to national follow-up','conditions':'Product, recipe, lot and distribution identity retained.','replication':'Reports describe one outbreak family; actions and affected people are not independent intervention studies.','mechanism':'Identify an implicated supply chain and prevent further availability or consumption; no extraction from food.','uncertainty':'No numerical reduction, residual-food treatment outcome or causal effect size is established for this control.','calculation':'No percentage calculated.','basis_yield_mass_balance':'No processing mass balance or matched food input/output.','other_contaminants':'Chromium attribution was reported in the linked investigation; paired control effects on any elements unresolved.','nutrition_quality_yield':'No applicable comparative measurements.','waste_destination':'Disposal advised for implicated products; environmental waste outcomes not quantified.','cost_status':'Implementation cost not quantified.','commercial_feasibility':'Recall and store audit were implemented; routine supplier-control effectiveness not measured.','applicability':'Only implicated finished-food context and clearly labelled procurement inference.','verification':'Retain exact product/lot identity and scoped test results; no universal lot-release cutoff supplied.','method':'Field investigation, product laboratory testing and recall audit; not an experiment.','funding_coi':'Public-health agency report; no independent efficacy trial inferred.','review':{'record_ref':'data/evidence/contracts/ingredient-rollout-2026-10-22/applesauce/source-review.json'},'extraction_gaps':[{'field':'quantitative treatment effect','next_action':'Requires applicable controlled food or exposure study; keep unquantified.'}], 'outcomes':[{'analyte':'Pb','direction':'context','period':'2023–2024 investigation and response','start':None,'end':None,'unit':'µg/kg','effect_label':'Unquantified exposure-prevention action' if idx==3 else 'Detection/verification; removal effect unquantified','endpoint':'Qualitative action, not a measured reduction in puree metal concentration','comparison':comp,'basis':'Finished-product investigation; no numerical treatment endpoint','locator':locator,'source_values_note':'No before/after food concentration pair or independent intervention sample count reported.'}]}
